import{_ as o,o as i,c as t,a2 as a}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0030 — Core del desktop compilato in WebAssembly per il workbench web","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0030-desktop-core-wasm.md","filePath":"adr/0030-desktop-core-wasm.md"}'),c={name:"adr/0030-desktop-core-wasm.md"};function d(n,e,s,r,l,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0030-—-core-del-desktop-compilato-in-webassembly-per-il-workbench-web" tabindex="-1">ADR-0030 — Core del desktop compilato in WebAssembly per il workbench web <a class="header-anchor" href="#adr-0030-—-core-del-desktop-compilato-in-webassembly-per-il-workbench-web" aria-label="Permalink to &quot;ADR-0030 — Core del desktop compilato in WebAssembly per il workbench web&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.3 (2026-11-02): §1.1, §1.2, §1.7, §2.5, §3.6, §4.1, §4.2, §4.4, App. A, C.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-29</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§1.2 (struttura del client), §3.4 (sync e merge sul client), §3.7 (index.db); ADR-0029, ADR-0020, D-07</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no di per sé: è la realizzazione tecnica di ADR-0029</td></tr></tbody></table><blockquote><p><strong>Nota (ADR-0051, accettata il 2026-11-20 e recepita in <code>Specifications.md</code> v1.8).</strong> Il codice Wails sta in <code>internal/shell</code> (l&#39;unico pacchetto che importa Wails v3); i binding TS non si leggono più da <code>frontend/wailsjs/go/app/*.d.ts</code> ma sono generati da <code>internal/app/gen/bindings</code>, e <code>App.Services()</code> è ancora l&#39;unico elenco dei servizi. Il nome <code>cmd/memobrain-core</code> è anteriore al rebrand (ADR-0052). Il testo qui sotto è storico e non cambia.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Il workbench web (ADR-0029) richiede le stesse funzioni del desktop. Sul desktop, gran parte di queste funzioni è in Go, in <code>apps/desktop/internal</code> (circa 24k LOC):</p><ul><li>indice SQLite FTS5 (<code>indexer</code>, <code>store</code>);</li><li>ricerca con linguaggio di query (<code>search</code>);</li><li>link, backlink e rename (<code>links</code>);</li><li><code>bases</code>, <code>templates</code>, <code>composer</code>, <code>graph</code>, <code>properties</code>;</li><li>history locale;</li><li>sync engine con merge 3-way (<code>sync</code>, <code>shared/go/merge</code>);</li><li>E2EE (<code>crypto</code>, <code>shared/go/vaultcrypto</code>);</li><li>importer.</li></ul><p>Per i vault privati il server non può eseguire nessuna di queste funzioni: devono girare nel browser.</p><p>L&#39;accoppiamento con l&#39;ambiente è concentrato in pochi punti:</p><ul><li>Wails solo in <code>internal/app</code> (eventi, dialoghi, finestra);</li><li>SQLite solo in <code>internal/store/store.go</code> (<code>sql.Open(&quot;sqlite&quot;)</code> con <code>modernc.org/sqlite</code>, che <strong>non compila</strong> per <code>js/wasm</code>);</li><li>l&#39;I/O su file con <code>os</code> in <code>vault</code>, <code>sync</code>, <code>history</code>, <code>indexer</code>, <code>links</code>, <code>store</code>, <code>app</code> e <code>importer</code>: su <code>GOOS=js</code> <code>os</code> passa da <code>globalThis.fs</code>, che la pagina può fornire (decisione 1).</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p>Il core del desktop viene compilato con <code>GOOS=js GOARCH=wasm</code> in <code>apps/desktop/cmd/memobrain-core</code> ed eseguito in un <strong>Web Worker dedicato</strong>.</p><ol><li><strong>File system: lo shim <code>fs</code> di Go, non un&#39;interfaccia <code>vfs</code>.</strong><ul><li>Su <code>GOOS=js</code> il pacchetto <code>os</code> di Go non chiama il sistema operativo: passa da <code>globalThis.fs</code> (lo stesso oggetto che <code>wasm_exec.js</code> riempie con <code>require(&quot;fs&quot;)</code> in Node). La pagina che ospita il core fornisce un <code>fs</code> basato su OPFS (<code>FileSystemSyncAccessHandle</code>, <code>rename</code> con <code>FileSystemFileHandle.move()</code>), quindi <strong>nessuna chiamata a <code>os</code> e nessun pacchetto Go va riscritto</strong>: <code>vault.FS</code>, <code>history</code>, <code>sync</code>, <code>importer</code> e <code>app</code> restano invariati, e con loro la scrittura atomica tmp + fsync + rename e il rifiuto del path traversal.</li><li>Sostituisce l&#39;interfaccia <code>internal/vfs</code> prevista nella prima stesura di questo ADR (circa 60 punti di chiamata a <code>os</code> da migrare). Il lavoro si sposta dal Go al JavaScript: lo shim <code>fs</code> si scrive e si prova in M9-WP5.</li><li><strong>Eccezione: i database SQLite non passano da <code>os</code>.</strong> Stanno nel VFS di sqlite-wasm (<code>opfs-sahpool</code>), invisibile allo shim. Ogni accesso a un database per percorso passa quindi da <code>internal/store</code>: <code>store.Open</code>, <code>store.Reset</code> e <code>store.Exists</code> (un controllo <code>os.Stat</code> su <code>sync.db</code> in <code>sync.ReadMount</code> è stato sostituito, perché sul web non avrebbe mai trovato il file).</li><li><strong>Le modifiche arrivano senza fsnotify.</strong> <code>vault.FS</code> ha un callback opzionale <code>SetOnChange</code>, chiamato dopo ogni <code>WriteFile</code>, <code>Mkdir</code>, <code>Rename</code>, <code>Trash</code> e <code>Delete</code> riusciti. Nel browser il callback inoltra a <code>watcher.Notify</code>, che applica gli stessi filtri e lo stesso debounce degli eventi; sul desktop non è registrato (fsnotify vede anche le modifiche di altri programmi).</li></ul></li><li><strong>SQLite.</strong><ul><li>Il driver si sceglie con un build tag in <code>internal/store</code> (<code>driver_native.go</code>, <code>!js</code>: <code>modernc.org/sqlite</code>; <code>driver_js.go</code>, <code>js</code>: <code>internal/sqlitejs</code>). Il nome del driver resta <code>sqlite</code> e la DSN è la stessa: <code>store.Open</code> non cambia.</li><li><code>internal/sqlitejs</code> è un driver <code>database/sql</code> che chiama in modo <strong>sincrono</strong> <code>globalThis.__memobrainSQLite</code>, un oggetto JavaScript nello stesso worker: <code>open</code>, <code>close</code>, <code>exec</code>, <code>query</code> e <code>fetch</code> (cursore a lotti di 256 righe), <code>closeCursor</code>, <code>deleteDatabase</code>, <code>exists</code>. Il lato JavaScript è <code>packages/sqlite-bridge</code> (<code>@memobrain/sqlite-bridge</code>) e non sa nulla di OPFS: riceve da chi lo installa la funzione che apre i database (<code>opfs-sahpool</code> nel browser, database in memoria nei test).</li><li>Formato dei valori sul confine: interi oltre 2^53 (gli <code>mtime_ns</code> lo sono) passano come <code>BigInt</code> in ingresso e come <code>{ i64: &quot;&lt;decimale&gt;&quot; }</code> in uscita; BLOB come <code>Uint8Array</code>; <code>time.Time</code> come testo RFC 3339. Le colonne dichiarate <code>DATE</code>, <code>DATETIME</code> o <code>TIMESTAMP</code> tornano come <code>time.Time</code> (come fa modernc: goose legge così <code>tstamp</code>); per questo il bridge riporta il tipo dichiarato di ogni colonna (<code>sqlite3_column_decltype</code>).</li><li><code>:memory:</code> apre un database privato per connessione, come in modernc.</li><li>Migrazioni goose, schema e query restano invariati.</li></ul></li><li><strong>Host.</strong><ul><li><code>internal/app</code> dipende da un&#39;interfaccia <code>Host</code> (<code>host.go</code>): eventi, dialoghi di salvataggio e apertura, <code>Delivered</code> (il file scelto è completo: il browser avvia il download), apertura URL, stampa, uscita, finestra, errori.</li><li><code>internal/shell/host.go</code> (<code>!js</code>, pacchetto della shell Wails) contiene il codice Wails di prima, compreso <code>OnSecondInstance</code>, mentre <code>internal/app/host_native.go</code> fornisce l&#39;host di default senza finestra; <code>host_web.go</code> (<code>js</code>) inoltra le chiamate a <code>globalThis.__memobrainHost</code>, attendendo le promise senza bloccare il ciclo di eventi. Fuori da <code>internal/shell</code> nessun binding importa Wails.</li><li><code>SaveFile</code> nel browser restituisce un percorso in <code>&lt;tmp&gt;/memobrain-downloads/</code>; <code>Delivered</code> lo trasforma in download.</li><li>Una costante <code>isWeb</code> (definita nei due file host) spegne ciò che il browser non ha: aggiornamenti (il motivo compare nello stato dell&#39;updater), cestino di sistema (si usa <code>.trash/</code> del vault), file watcher. <code>SettingsAPI.Info</code> espone <code>platform: &quot;desktop&quot; | &quot;web&quot;</code>, che la UI userà per le capability di M9-WP4.</li></ul></li><li><strong>RPC.</strong><ul><li><code>internal/rpc</code> (Go puro, senza build tag) è un dispatcher per nome: <code>Call(service, method, argsJSON) → resultJSON</code>. Segue la semantica di Wails: tutti e soli i metodi esportati di uno struct registrato; argomenti come array JSON, uno per parametro; nessun risultato, un valore, un errore o valore + errore (un errore non nullo rifiuta la chiamata col suo messaggio); <code>[]byte</code> in base64, <code>time.Time</code> in RFC 3339, slice nil come <code>null</code>. Un metodo variadico o con più di un valore oltre all&#39;errore si rifiuta già alla registrazione, come Wails; un panic diventa un errore.</li><li><code>App.Services()</code> (<code>internal/app/services.go</code>) è l&#39;<strong>unico elenco</strong> dei servizi: lo usano <code>main.go</code> per Wails e <code>cmd/memobrain-core</code> per il dispatcher, quindi le due API non possono divergere.</li><li><code>cmd/memobrain-core</code> (<code>js</code>) pubblica <code>globalThis.__memobrainCore</code> con <code>call(service, method, argsJSON) → Promise&lt;string&gt;</code>, <code>start()</code> (OnStartup di Wails), <code>domReady()</code>, <code>shutdown()</code> e <code>methods()</code>. Ogni chiamata gira in una goroutine propria, perché un&#39;attesa dentro una callback JavaScript fermerebbe il ciclo di eventi. La configurazione si legge da <code>globalThis.__memobrainConfig = { dataDir, version, logLevel }</code>; il log va alla console; <code>__memobrainCoreReady()</code> (se definita) è chiamata quando il core è pronto. Gli eventi Go → TypeScript escono dall&#39;<code>Emit</code> dell&#39;host (<code>__memobrainHost.emit(name, json)</code>).</li><li>Su altre piattaforme <code>cmd/memobrain-core</code> stampa come compilarlo ed esce con 2.</li><li>Lato pagina, il bridge (<code>web/src/workbench/bridge.ts</code>, WP5) installa <code>window.go.app.*</code> e <code>window.runtime.*</code> come fa oggi <code>installWailsMock()</code>.</li><li>Test di parità: <code>TestDispatcherExposesEveryService</code> (ogni servizio si registra e ne espone tutti i metodi) e <code>TestDispatcherMatchesTheGeneratedBindings</code> (i metodi dichiarati in <code>frontend/wailsjs/go/app/*.d.ts</code> sono esattamente quelli del dispatcher; si salta se i binding non sono generati con <code>make gen-wails</code>).</li></ul></li><li><strong>Rete e auth.</strong><ul><li><code>net/http</code> su <code>js/wasm</code> usa la Fetch API: il client cloud del desktop funziona senza modifiche, con base URL same-origin.</li><li><strong>Sessione ospitata.</strong> Se l&#39;host implementa <code>SessionHost</code>, <code>auth.Service</code> parte in modalità <code>Hosted</code> (<code>auth/hosted.go</code>): niente flusso nel browser di sistema, niente refresh token, niente keychain. Il token di accesso lo dà la pagina (<code>oidc-client-ts</code> di <code>web/src/auth</code>) a ogni richiesta (<code>__memobrainHost.token()</code>); profilo e registrazione del dispositivo (<code>platform: &quot;web&quot;</code>) avvengono come sul desktop, e il dispositivo registrato resta in <code>auth.json</code> tra un accesso e l&#39;altro. Se cambia l&#39;account, la registrazione vecchia si scarta (vale anche sul desktop).</li><li>Le chiavi dei vault privati stanno in un <code>crypto.MemoryStore</code>: nessun keychain del sistema operativo.</li><li>Le notifiche usano il fallback SSE che il client già ha (<code>/api/v1/events</code>, <code>transport/notify.go</code>): la sessione ospitata non annuncia l&#39;endpoint gRPC, quindi il client va diretto su SSE.</li></ul></li><li><strong>Esclusi o neutralizzati nel build <code>js</code>:</strong> <code>updater</code> (compila, con <code>detach</code> vuoto; disattivato da <code>isWeb</code>), <code>watcher</code> (sorgente di eventi vuota, vedi punto 1), keychain di sistema e cestino di sistema.</li><li><strong>Build e consegna.</strong><ul><li><code>make wasm-core</code> produce <code>memobrain-core.wasm</code> (<code>-trimpath -ldflags &quot;-s -w&quot;</code>, poi <code>wasm-opt -Oz</code> se disponibile) insieme a <code>wasm_exec.js</code> della stessa toolchain.</li><li>Gli asset sono copiati con hash e SRI dalla build di <code>web/</code> e serviti precompressi (brotli) dal cloud.</li><li>Lo stesso target entra nel <code>Dockerfile</code> del cloud (stage dedicato).</li></ul></li><li><strong>Test.</strong><ul><li><code>make test-wasm</code> esegue i test Go di <strong>tutto</strong> <code>apps/desktop/internal/...</code> e <code>cmd/...</code> sotto <code>GOOS=js GOARCH=wasm</code> in Node (<code>scripts/go-js-exec.sh</code>), con il bridge installato da <code>packages/sqlite-bridge/src/go-test-preload.ts</code>. È più semplice di un browser e usa lo stesso V8 e lo stesso sqlite-wasm; resta da fare l&#39;esecuzione in un browser vero per OPFS (M9-WP5/WP7).</li><li>Nel banco di prova ogni percorso è un database in memoria con nome, tenuto vivo da una connessione «custode» (un file sopravvive alle connessioni); i percorsi si canonicalizzano (<code>/var</code> e <code>/private/var</code> su macOS sono lo stesso file).</li><li>Il job CI <code>wasm-core</code> e le conformance <code>shared/conformance</code> nel WASM restano da aggiungere (M9-WP7).</li></ul></li></ol><h2 id="esito-dello-spike-m9-wp1-2026-10-29" tabindex="-1">Esito dello spike (M9-WP1, 2026-10-29) <a class="header-anchor" href="#esito-dello-spike-m9-wp1-2026-10-29" aria-label="Permalink to &quot;Esito dello spike (M9-WP1, 2026-10-29)&quot;">​</a></h2><p>Metodo: build di prova con un overlay di <code>go build</code> (nessun file del repo modificato) su Go 1.27.3, macOS arm64, Node 24 (V8, come Chrome). Il benchmark SQLite usa <code>@sqlite.org/sqlite-wasm</code> 3.54.1 e le migrazioni reali di <code>internal/store/migrations/index</code>, con un database in memoria. <strong>Non misurato in un browser</strong>: OPFS e il driver <code>database/sql</code> non esistono ancora.</p><table tabindex="0"><thead><tr><th>Misura</th><th>Obiettivo</th><th>Risultato</th><th>Esito</th></tr></thead><tbody><tr><td>Compilazione <code>GOOS=js</code> del core</td><td>compila</td><td>Tutti i pacchetti di logica e <code>internal/app</code> (Wails incluso) compilano. Unico blocco reale: <code>modernc.org/sqlite</code> (<code>libc</code> non ha file per <code>js</code>). <code>updater</code> fallisce su <code>syscall.SysProcAttr.Setsid</code></td><td>ok con lavoro</td></tr><tr><td>Dimensione <code>.wasm</code> compressa (brotli)</td><td>≤ ~8 MB</td><td>36,6 MB grezzi, <strong>6,4 MB brotli</strong> (7,9 MB gzip) con <code>-trimpath -ldflags &quot;-s -w&quot;</code>, tutti i 20 servizi dei binding (122 metodi) e Wails, senza <code>wasm-opt</code></td><td>ok, margine ridotto</td></tr><tr><td><code>sqlite3.wasm</code> (sqlite-wasm)</td><td>≤ 1,5 MB</td><td>0,88 MB grezzi</td><td>ok</td></tr><tr><td>Avvio a freddo del core</td><td>≤ 2 s</td><td><code>app.New</code> e registrazione dei binding in 0,1 s in Node (V8, file locale). Nel browser va aggiunto il download</td><td>ok (parziale)</td></tr><tr><td>FTS5 <code>trigram</code> e migrazioni su sqlite-wasm</td><td>funzionano</td><td>Le due migrazioni reali (indice) si applicano; FTS5 <code>trigram case_sensitive 0</code> funziona; versione SQLite 3.54.1. Goose non è stato provato (serve il driver Go)</td><td>ok (parziale)</td></tr><tr><td>Indicizzazione di 5k note</td><td>&lt; 60 s</td><td>Solo SQLite: 5.000 note, 26 MB di testo, <strong>1,7 s</strong>. Parser Go sotto WASM: 1,58 MB/s (nativo 7,2 MB/s, quindi <strong>4,5× più lento</strong>), cioè ≈ 17 s per 26 MB. Stima totale ≈ 20–25 s</td><td>ok per stima</td></tr><tr><td>Ricerca FTS, p95</td><td>≤ 2× il desktop</td><td><strong>4,4 ms</strong> (p50 3,6 ms) su 5k note. Il confronto con il desktop nativo non è stato fatto; il valore assoluto è molto sotto i 200 ms di ADR-0020</td><td>non confrontato</td></tr><tr><td>Memoria con 5k note</td><td>≤ 512 MB</td><td>RSS di Node 303 MB con il solo database SQLite. Heap del core Go e cache di ricerca non misurati</td><td>aperto</td></tr></tbody></table><p>Non verificato dallo spike (stato dopo M9-WP2 in &quot;Esito dell&#39;implementazione&quot;):</p><ol><li><s>Driver <code>database/sql</code> su sqlite-wasm con chiamate sincrone da Go</s>: <strong>fatto in WP2</strong>, provato in Node con tutti i test del core. Restano il VFS <code>opfs-sahpool</code> e le prestazioni reali in un browser.</li><li>File system su OPFS (<code>FileSystemSyncAccessHandle</code>): scrittura atomica, <code>Walk</code>, sync su vault di migliaia di file. Con lo shim <code>fs</code> (decisione 1) è lavoro JavaScript di WP5.</li><li>Indicizzazione end-to-end e memoria con l&#39;indexer reale, <code>search</code> e la cache dei candidati, in un browser.</li><li>Ricerca a confronto con il desktop nativo sullo stesso dataset.</li></ol><p><strong>Parere: via libera provvisorio.</strong> Nessun dato contraddice l&#39;approccio. Il costo principale è la velocità del codice Go sotto WASM (≈ 4,5× più lento del nativo sul parser), che per 5k note resta nei limiti. Per vault grandi (50k note, ≈ 73 s nativi in ADR-0020) l&#39;indicizzazione iniziale nel browser stimata supera i 5 minuti: va fatta in background con avanzamento, e l&#39;indice può essere costruito in modo incrementale durante il pull.</p><p>Se un modulo non rispetta gli obiettivi, il fallback riguarda solo quel modulo: implementazione TS verificata con le stesse fixture, o caricamento differito. Il resto del core rimane in WASM. La cache di ricerca in RAM di ADR-0020 (circa 210 MB a 50k note) va limitata nel build <code>js</code> con un budget più basso.</p><h2 id="esito-dell-implementazione-m9-wp2-2026-10-29" tabindex="-1">Esito dell&#39;implementazione (M9-WP2, 2026-10-29) <a class="header-anchor" href="#esito-dell-implementazione-m9-wp2-2026-10-29" aria-label="Permalink to &quot;Esito dell&#39;implementazione (M9-WP2, 2026-10-29)&quot;">​</a></h2><p>Realizzati e provati: driver <code>sqlitejs</code> e bridge, <code>store</code>, <code>Host</code>, <code>SetOnChange</code>/<code>Notify</code>, sessione ospitata, <code>isWeb</code>, <code>make test-wasm</code>.</p><ul><li><strong>Desktop invariato:</strong> <code>go test ./...</code> e <code>golangci-lint</code> (pacchetti toccati) passano; il comportamento nativo non è cambiato (nessun test nativo modificato, salvo <code>config_test</code>, che registra il driver tramite <code>store</code>).</li><li><strong>Core sotto WASM:</strong> tutti i 27 pacchetti di <code>apps/desktop/internal/...</code> passano in Node con sqlite-wasm: indexer (13 s), search, links, bases, graph, history, importer, crypto, sync, auth e <code>app</code>, compresi i test dei binding. Test saltati su <code>js</code>: la prova di crash di <code>vault</code> (serve <code>fork/exec</code>) e <code>watcher</code> con fsnotify (sostituito da <code>TestNotifyDebouncesAndCoalesces</code>, che gira anche in nativo).</li><li><strong>Bug trovati dai test sotto WASM e corretti:</strong> (1) <code>sync.ReadMount</code> cercava <code>sync.db</code> con <code>os.Stat</code>; (2) le colonne <code>TIMESTAMP</code> tornavano come stringhe e goose non riconosceva la tabella delle versioni; (3) <code>updater</code> non compilava per <code>js</code>.</li><li><strong>Non verificato (resta in WP5 e WP7):</strong> lo shim <code>fs</code> su OPFS e il VFS <code>opfs-sahpool</code> in un browser; la lettura dello stream SSE nel browser; le prestazioni dell&#39;indicizzazione end-to-end con OPFS.</li><li><strong>Correzione (2026-10-29, M9-WP3):</strong> il target <code>make test-wasm</code>, descritto qui sopra e in roadmap, non era stato scritto nel <code>Makefile</code> quando il WP2 è stato dichiarato chiuso (la modifica non si era applicata, e non ho ricontrollato). Le suite sotto WASM erano state eseguite con il comando completo, non con <code>make</code>. Il target esiste dal WP3 e l&#39;ho eseguito.</li></ul><h2 id="esito-dell-implementazione-m9-wp3-2026-10-29" tabindex="-1">Esito dell&#39;implementazione (M9-WP3, 2026-10-29) <a class="header-anchor" href="#esito-dell-implementazione-m9-wp3-2026-10-29" aria-label="Permalink to &quot;Esito dell&#39;implementazione (M9-WP3, 2026-10-29)&quot;">​</a></h2><p>Realizzati e provati: <code>internal/rpc</code>, <code>App.Services()</code>, <code>cmd/memobrain-core</code>, <code>make wasm-core</code>, <code>make test-wasm</code>.</p><ul><li><strong>Dimensione reale:</strong> <code>make wasm-core</code> produce <code>memobrain-core.wasm</code> di 36,7 MB, <strong>6,44 MB con brotli</strong> (obiettivo ≤ 8 MB), con tutti i 20 servizi (122 metodi) e Wails incluso, senza <code>wasm-opt</code>. Coincide con la misura dello spike.</li><li><strong>Prova del binario vero in Node</strong> (script fuori dal repo): <code>methods()</code> riporta 122 metodi, <code>start()</code> apre <code>app.db</code>, <code>SettingsAPI.Info</code> risponde <code>platform: &quot;web&quot;</code> con la versione stampata nella configurazione, un servizio inesistente rifiuta la promise, <code>shutdown()</code> termina.</li><li><strong>Test:</strong> <code>TestCoreAnswersBindingCallsThroughThePage</code> (sotto <code>js</code>) attraversa Promise JavaScript → dispatcher → binding reali → sessione ospitata; il dispatcher ha test di conversione, errori, panic e registrazione; la parità con i binding generati passa (122 metodi, 20 servizi) in nativo e sotto WASM. <code>make test-wasm</code>: 29 pacchetti ok; nativo <code>go test -race ./...</code>: 28 ok; <code>golangci-lint</code> pulito.</li><li><strong>Non verificato:</strong> il caricamento in un Web Worker vero (<code>wasm_exec.js</code> del browser, <code>WebAssembly.instantiateStreaming</code>) e il bridge <code>window.go</code> (WP5); il comportamento di <code>app.Startup</code> con OPFS.</li></ul><h2 id="esito-dell-implementazione-m9-wp5-2026-10-29" tabindex="-1">Esito dell&#39;implementazione (M9-WP5, 2026-10-29) <a class="header-anchor" href="#esito-dell-implementazione-m9-wp5-2026-10-29" aria-label="Permalink to &quot;Esito dell&#39;implementazione (M9-WP5, 2026-10-29)&quot;">​</a></h2><p>Provato in un Chromium vero (Playwright), con il core reale e senza cloud:</p><ul><li><strong>Shim <code>fs</code> su OPFS</strong> (<code>web/src/workbench/opfs-fs.ts</code>): 9 test in un worker. Scoperto che <code>FileSystemFileHandle.move()</code> <strong>sostituisce</strong> un file esistente (serve alla scrittura atomica di <code>vault.FS</code>) ma <code>move()</code> <strong>non esiste per le cartelle</strong> in Chromium: il rename di una cartella copia l&#39;albero e rimuove l&#39;originale.</li><li><strong>SQLite su <code>opfs-sahpool</code></strong>: migrazioni goose, FTS5 <code>trigram</code>, ricerca e indice sopravvivono al reload. Il pool ha una capacità fissa (64 file riservati all&#39;avvio, perché non si può allargare da codice sincrono): è un limite sul numero di vault e di journal aperti contemporaneamente.</li><li><strong>Dimensioni reali:</strong> core 35,9 MB raw, 7,84 MB gzip (6,4 MB brotli); sqlite 0,86 MB, 0,4 MB gzip. Avvio a freddo nel test: 1–2 s dalla pagina al vault mostrato, con i file già in cache locale.</li><li><strong>Bug trovato dall&#39;e2e:</strong> in <code>MEMOBRAIN_E2E</code> il montaggio installava il mock di Wails sopra il bridge, e i primi test «riusciti» giravano contro il mock. Ora <code>kind: &#39;web&#39;</code> non installa mai il mock; la prova che risponde il core vero è <code>SettingsAPI.Info().platform === &#39;web&#39;</code> e l&#39;hash reale dei file.</li><li><strong>Non verificato:</strong> Safari e Firefox (<code>move()</code> e i worker modulari vanno controllati), il tempo di indicizzazione di vault grandi nel browser (stima del WP1: &gt; 5 minuti a 50k note), la memoria del core con vault reali, l&#39;uso con un cloud vero.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Interfaccia <code>vfs</code> in Go al posto dello shim <code>fs</code></strong> (la scelta della prima stesura): scartata dopo aver visto che <code>os</code> su <code>js</code> è già un punto di estensione. Avrebbe richiesto di migrare circa 60 chiamate in otto pacchetti e di ripetere nei test le garanzie di scrittura atomica, per un guadagno nullo.</li><li><strong>Port in TypeScript della logica Go</strong>: scartato. Circa 10k LOC da riscrivere (Bases da sola ne conta circa 2,8k) e due implementazioni da tenere allineate per sempre, quando l&#39;obiettivo esplicito è la parità di comportamento.</li><li><strong><code>ncruces/go-sqlite3</code></strong>: scartato. Esegue SQLite con wazero, cioè un interprete WASM dentro WASM: troppo lento nel browser.</li><li><strong>TinyGo</strong>: scartato. Il supporto alla reflection e a <code>database/sql</code> non basta per il core attuale; da rivalutare solo per ridurre la dimensione.</li><li><strong>Calcolo nel cloud</strong>: scartato in ADR-0029.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Una sola implementazione della logica di vault, con test comuni. Ogni correzione al core vale per desktop e web.</li><li>Refactoring del desktop (VFS, <code>Host</code>, driver SQL) a rischio controllato: deve restare verde a ogni passo con i test esistenti.</li><li>Il download del WASM è grande (diversi MB), ma solo per chi apre il workbench e in cache dopo il primo accesso.</li><li>La toolchain Go entra nella build della Web UI: Dockerfile, CI e <code>make web-build</code> dipendono da <code>make wasm-core</code>.</li></ul><p><strong>Aggiornamento 2026-11-02:</strong> l&#39;owner ha accettato l&#39;ADR, recepito in <code>Specifications.md</code> v1.3 (§1.7). Superati rispetto al testo sopra: lo stato «via libera provvisorio» dello spike (il core gira in produzione nel workbench web); il job CI <code>wasm-core</code> e le conformance nel WASM «da aggiungere» (non c&#39;è un servizio di CI: <code>task test-wasm</code> è in <code>task ci</code>, ADR-0036); il client gRPC non è più compilato nel build <code>js</code> (<code>notify_grpc.go</code> con <code>//go:build !js</code>, solo SSE), e il core è sceso a circa 6,75 MB gzip contro un budget di 8 MB (<code>docs/web-ui.md</code>); i target <code>make …</code> sono <code>task …</code> (ADR-0032).</p>',33)])])}const g=o(c,[["render",d]]);export{u as __pageData,g as default};
